{(event) => {
                                    if (event.nativeEvent.isComposing) return;
                                    if (event.key === "Enter" || event.key === "ArrowDown") {
                                      event.preventDefault();
                                      void commitPendingCorrection(
                                        entry,
                                        neighborLearnerId(entry.learnerId, 1),
                                      );
                                    } else if (event.key === "ArrowUp") {
                                      event.preventDefault();
                                      void commitPendingCorrection(
                                        entry,
                                        neighborLearnerId(entry.learnerId, -1),
                                      );
                                    } else if (event.key === "Escape") {
                                      event.preventDefault();
                                      if (!isSaving) cancelPendingCorrection(entry.learnerId);
                                    }
                                  }}

{(event) => {
                                    if (event.nativeEvent.isComposing) return;
                                    if (event.key === "Enter" || event.key === "ArrowDown") {
                                      event.preventDefault();
                                      void commitScoreDraft(
                                        entry,
                                        neighborLearnerId(entry.learnerId, 1),
                                      );
                                    } else if (event.key === "ArrowUp") {
                                      event.preventDefault();
                                      void commitScoreDraft(
                                        entry,
                                        neighborLearnerId(entry.learnerId, -1),
                                      );
                                    } else if (event.key === "Tab") {
                                      // CTOS M07: without this, native Tab
                                      // leaves the score grid and walks the
                                      // row's Excused/N/A buttons instead of
                                      // the next learner's score — a
                                      // gradebook that costs a keystroke plus
                                      // a mouse per row. Like Enter, this
                                      // commits the draft first and only moves
                                      // focus on a successful save, so Tab
                                      // never silently drops an entry.
                                      const neighbor = neighborLearnerId(
                                        entry.learnerId,
                                        event.shiftKey ? -1 : 1,
                                      );
                                      const text = draftScoreFor(
                                        entry.learnerId,
                                        entry.score,
                                      ).trim();
                                      const changed =
                                        text !== "" &&
                                        text !== (entry.score === null ? "" : String(entry.score));
                                      // Clean/restored inputs use native traversal so every
                                      // row's history and exception controls stay reachable.
                                      if (neighbor && changed) {
                                        event.preventDefault();
                                        void commitScoreDraft(entry, neighbor);
                                      }
                                      // At the boundary native Tab leaves the grid;
                                      // blur still runs the same commit/validation.
                                    } else if (event.key === "Escape") {
                                      event.preventDefault();
                                      setScoreDrafts((current) => {
                                        const next = { ...current };
                                        delete next[entry.learnerId];
                                        return next;
                                      });
                                    }
                                  }}

